#
# MAKH UFUZZ U7 — program batches for the guest `run-ir` path.
#
#   u7_batch.py sample OUT.ir
#       the run-ir equivalence sample baked into the initrd: SAMPLE programs
#       regenerated by build/u4gen, with the generator's expectations
#   u7_batch.py image BATCH.ir OUT.img
#       a copy of build/ext2.img with BATCH.ir written to /u7/batch.ir
#       (the guest mounts the image at /mnt) — no ISO rebuild needed
#
# A batch file is the U3 IR (with U5.3 `=expect` annotations and an optional
# `need` line) for programs 0..N-1, each preceded by `### prog <k>`, after a
# first line `# u7 batch count=<N>`.

import os
import shutil
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, ".."))
U4GEN = os.path.join(ROOT, "build", "u4gen")
EXT2 = os.path.join(ROOT, "build", "ext2.img")

# mode, base, mut — kernel/tests/test_ufuzz.c (u7_sample) holds the same list.
SAMPLE = [(0, 1, 1), (1, 7, 7), (2, 3, 3), (5, 3, 23758), (5, 11, 63353), (6, 0, 0)]


def gen_ir(mode, base, mut, u4gen=U4GEN):
    """One program from the C generator, without its `### seed` header."""
    out = subprocess.run([u4gen, str(base), "1", str(mode), str(mut)], capture_output=True,
                         text=True, check=True).stdout
    return "\n".join(l for l in out.splitlines() if not l.startswith("### ")).strip("\n") + "\n"


def render(programs):
    """Batch text for a list of IR program strings."""
    out = ["# u7 batch count=%d" % len(programs)]
    for k, ir in enumerate(programs):
        out.append("### prog %d" % k)
        out.append(ir.strip("\n"))
    return "\n".join(out) + "\n"


def debugfs_available():
    return shutil.which("debugfs") is not None


def make_image(batch_path, out_img, base_img=EXT2, virgin=None):
    """Copy the ext2 test image and write the batch to /u7/batch.ir in the copy;
    with `virgin` (U8), also the global coverage virgin map to /u8/virgin.bin."""
    if not debugfs_available():
        raise RuntimeError("debugfs not found (install e2fsprogs)")
    if not os.path.exists(base_img):
        raise RuntimeError("%s missing (make build/ext2.img)" % base_img)
    shutil.copyfile(base_img, out_img)
    # Fixed command text; the only variable part is a path we created.
    cmds = "mkdir /u7\nwrite %s /u7/batch.ir\n" % os.path.abspath(batch_path)
    if virgin is not None:
        cmds += "mkdir /u8\nwrite %s /u8/virgin.bin\n" % os.path.abspath(virgin)
    r = subprocess.run(["debugfs", "-w", "-f", "-", out_img], input=cmds, text=True,
                       capture_output=True)
    if r.returncode != 0:
        raise RuntimeError("debugfs failed: %s" % r.stderr.strip())
    chk = subprocess.run(["debugfs", "-R", "stat /u7/batch.ir", out_img], capture_output=True,
                         text=True)
    if "Inode:" not in chk.stdout:
        raise RuntimeError("batch not present in %s" % out_img)
    if virgin is not None:
        chk = subprocess.run(["debugfs", "-R", "stat /u8/virgin.bin", out_img],
                             capture_output=True, text=True)
        if "Inode:" not in chk.stdout:
            raise RuntimeError("virgin map not present in %s" % out_img)
    return out_img


def main(argv):
    if len(argv) == 2 and argv[0] == "sample":
        with open(argv[1], "w") as f:
            f.write(render([gen_ir(m, b, c) for m, b, c in SAMPLE]))
        return 0
    if len(argv) == 3 and argv[0] == "image":
        make_image(argv[1], argv[2])
        return 0
    print("usage: u7_batch.py sample OUT.ir | image BATCH.ir OUT.img", file=sys.stderr)
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
